    limitations: ["Evidence is retrospective; no randomised trial of extent of surgery", "Residual disease at re-resection carries stage IV-like survival whatever is removed", "Hepatic-side T2 and all T3 tumours recur often despite radical surgery; adjuvant capecitabine is the only proven addition"],
    cancers: [GB, "incidental-gallbladder-cancer"], terms: ["radical-cholecystectomy", "simple-cholecystectomy", "segment-ivb-v-resection", "port-site-metastasis", "t2a-versus-t2b", "cystic-duct-margin", "hepatectomy", "lymphadenectomy", "staging-laparoscopy", "minimally-invasive-surgery"], technologies: ["robotic-surgery"],
